// --- BASE64 SABLON ÉS CÉGES ALÁÍRÁS ---
const TEMPLATE_company_sign_n_stamp = "data:image/png;base64,"// --- BASE64 SABLON ---
const TEMPLATE_B64_CIM = ""

// Globális tárolók a generált Blob objektumoknak
let generatedContractBlob = null;
let generatedDeclaratieBlob = null;

let canvas = null;
let ctx = null;
let isDrawing = false;
let hasSigned = false;

// --- DOM BETÖLTÉSE ÉS INICIALIZÁLÁS ---
document.addEventListener('DOMContentLoaded', () => {
  canvas = document.getElementById('signatureCanvas');
  if (canvas) {
    ctx = canvas.getContext('2d');
    
    // Fehér háttér biztosítása
    ctx.fillStyle = "#ffffff";
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.strokeStyle = '#0400ff';
    ctx.lineWidth = 2.5;
    ctx.lineCap = 'round';

    // Egér eseménykezelők
    canvas.addEventListener('mousedown', startDrawing);
    canvas.addEventListener('mousemove', draw);
    canvas.addEventListener('mouseup', stopDrawing);
    canvas.addEventListener('mouseleave', stopDrawing);

    // Érintőképernyős (Touch) eseménykezelők
    canvas.addEventListener('touchstart', startDrawing, { passive: false });
    canvas.addEventListener('touchmove', draw, { passive: false });
    canvas.addEventListener('touchend', stopDrawing);
  }

  // Aláírás törlése gomb
  const clearBtn = document.getElementById('clearSignatureBtn');
  if (clearBtn) {
    clearBtn.addEventListener('click', () => {
      if (ctx && canvas) {
        ctx.fillStyle = "#ffffff";
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        hasSigned = false;
      }
    });
  }
});

// --- CANVAS RAJZOLÓ LOGIKA ---
function getPos(e) {
  const rect = canvas.getBoundingClientRect();
  const clientX = e.touches ? e.touches[0].clientX : e.clientX;
  const clientY = e.touches ? e.touches[0].clientY : e.clientY;
  return {
    x: (clientX - rect.left) * (canvas.width / rect.width),
    y: (clientY - rect.top) * (canvas.height / rect.height)
  };
}

function startDrawing(e) {
  isDrawing = true;
  hasSigned = true;
  const pos = getPos(e);
  ctx.beginPath();
  ctx.moveTo(pos.x, pos.y);
  if (e.touches) e.preventDefault();
}

function draw(e) {
  if (!isDrawing) return;
  const pos = getPos(e);
  ctx.lineTo(pos.x, pos.y);
  ctx.stroke();
  if (e.touches) e.preventDefault();
}

function stopDrawing() {
  isDrawing = false;
}

// --- SEGÉDFÜGGVÉNYEK ---
function getFormData() {
  const numeVal = document.getElementById('nume')?.value.trim() || '';
  const emailVal = document.getElementById('email')?.value.trim() || '';
  const cnpVal = document.getElementById('cnp')?.value.trim() || '';

  return {
    nume: numeVal,
    Nume: numeVal,
    nume_candidat: numeVal,
    salariat: numeVal,
    email: emailVal,
    cnp: cnpVal,
    data_completare: new Date().toLocaleDateString('ro-RO')
  };
}

function checkIfDeclaratieNeeded() {
  const checkEl = document.getElementById('needsDeclaratie');
  return checkEl ? checkEl.checked : false; 
}

// --- BASE64 KÉP TÖMÖRÍTŐ ÉS ARÁNYTARTÓ SEGÉDFÜGGVÉNY ---
function compressBase64Image(base64Str, maxWidth = 400, maxHeight = 250) {
  return new Promise((resolve) => {
    if (!base64Str) return resolve("");
    const formattedSrc = base64Str.startsWith('data:') ? base64Str : 'data:image/png;base64,' + base64Str;
    const img = new Image();
    img.onload = () => {
      const c = document.createElement('canvas');
      let w = img.width;
      let h = img.height;
      
      const ratio = Math.min(maxWidth / w, maxHeight / h, 1);
      w = Math.round(w * ratio);
      h = Math.round(h * ratio);

      c.width = w;
      c.height = h;
      const cCtx = c.getContext('2d');
      cCtx.drawImage(img, 0, 0, w, h);
      resolve(c.toDataURL('image/png'));
    };
    img.onerror = () => resolve(formattedSrc);
    img.src = formattedSrc;
  });
}

// --- DOCX GENERÁLÓ LOGIKA ---
async function buildDocxBlob(templateSource, includeCompanySignature = false) {
  let arrayBuffer;

  if (templateSource.startsWith('http') || templateSource.startsWith('/') || templateSource.startsWith('templates/')) {
    const response = await fetch(templateSource);
    if (!response.ok) {
      throw new Error(`Nem található a sablonfájl (${response.status}: ${response.statusText})`);
    }
    arrayBuffer = await response.arrayBuffer();
  } else {
    const binaryString = window.atob(templateSource);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }
    arrayBuffer = bytes.buffer;
  }

  const zip = new PizZip(arrayBuffer);

  const opts = {
    centered: false,
    getImage: function (tagValue) {
      if (!tagValue) return new ArrayBuffer(0);
      const base64Data = tagValue.split(',')[1] || tagValue;
      const binaryString = window.atob(base64Data);
      const len = binaryString.length;
      const bytes = new Uint8Array(len);
      for (let i = 0; i < len; i++) {
        bytes[i] = binaryString.charCodeAt(i);
      }
      return bytes.buffer;
    },
    getSize: function () {
      return [180, 110];
    }
  };

  const ImageModuleRef = window.ImageModule || ImageModule;
  const imageModule = new ImageModuleRef(opts);

  const doc = new window.docxtemplater(zip, {
    modules: [imageModule],
    paragraphLoop: true,
    linebreaks: true
  });

  const formData = getFormData();

  // 1. Jelentkező aláírása
  if (hasSigned && canvas) {
    const sigImg = canvas.toDataURL('image/png');
    formData.applicant_signature = sigImg;
    formData.semnatura = sigImg;
  }

  // 2. Céges aláírás és pecsét kezelése
  const rawCompanySig = (typeof TEMPLATE_company_sign_n_stamp !== 'undefined' && TEMPLATE_company_sign_n_stamp)
    ? TEMPLATE_company_sign_n_stamp
    : ((typeof company_sign_n_stamp !== 'undefined' && company_sign_n_stamp)
      ? company_sign_n_stamp
      : ((typeof TEMPLATE_compSignature !== 'undefined' && TEMPLATE_compSignature) ? TEMPLATE_compSignature : null));

  if (includeCompanySignature && rawCompanySig) {
    const compressedSig = await compressBase64Image(rawCompanySig);
    formData.company_signature = compressedSig;
    formData.semnatura_angajator = compressedSig;
    formData.company_signature_and_stamp = compressedSig;
    formData.company_sign_n_stamp = compressedSig;
  } else {
    formData.company_signature = "";
    formData.semnatura_angajator = "";
    formData.company_signature_and_stamp = "";
    formData.company_sign_n_stamp = "";
  }

  doc.render(formData);

  return doc.getZip().generate({
    type: "blob",
    mimeType: "application/vnd.openxmlformats-officedocument.wordprocessingml.document"
  });
}

// --- ELŐNÉZET ÉS MODAL NYITÁSA (Céges aláírás NÉLKÜL) ---
async function generateAndPreview() {
  const nume = document.getElementById('nume')?.value.trim();
  const email = document.getElementById('email')?.value.trim();
  const cnp = document.getElementById('cnp')?.value.trim();

  if (!nume || !email || !cnp) {
    alert("Vă rugăm să completați toate câmpurile obligatorii!");
    return;
  }

  if (!hasSigned) {
    alert("Vă rugăm să semnați contractul înainte de a vedea previzualizarea!");
    return;
  }

  try {
    const templatePath = (typeof TEMPLATE_B64_CIM !== 'undefined' && TEMPLATE_B64_CIM)
      ? TEMPLATE_B64_CIM
      : 'templates/contract_template.docx';

    generatedContractBlob = await buildDocxBlob(templatePath, false);

    const contractContainer = document.getElementById('contractPreviewContainer');
    if (contractContainer) {
      contractContainer.innerHTML = '';
      await docx.renderAsync(generatedContractBlob, contractContainer);
    }

    const requiresDeclaratie = checkIfDeclaratieNeeded();
    const declaratieTabBtn = document.getElementById('declaratieTabBtn');

    if (requiresDeclaratie) {
      const declaratiePath = (typeof TEMPLATE_B64_DECLARATIE !== 'undefined' && TEMPLATE_B64_DECLARATIE)
        ? TEMPLATE_B64_DECLARATIE
        : 'templates/declaratie_template.docx';

      generatedDeclaratieBlob = await buildDocxBlob(declaratiePath, false);
      
      const declaratieContainer = document.getElementById('declaratiePreviewContainer');
      if (declaratieContainer) {
        declaratieContainer.innerHTML = '';
        await docx.renderAsync(generatedDeclaratieBlob, declaratieContainer);
      }

      if (declaratieTabBtn) declaratieTabBtn.style.display = 'inline-block';
    } else {
      if (declaratieTabBtn) declaratieTabBtn.style.display = 'none';
      generatedDeclaratieBlob = null;
    }

    switchDocTab('contract');
    
    const modal = document.getElementById('documentPreviewModal');
    if (modal) modal.style.display = 'block';

  } catch (error) {
    console.error("Hiba a dokumentum generálásakor:", error);
    alert("Hiba történt a dokumentum előnézetének elkészítésekor: " + error.message);
  }
}

function switchDocTab(tabName) {
  const contractContainer = document.getElementById('contractPreviewContainer');
  const declaratieContainer = document.getElementById('declaratiePreviewContainer');
  const tabs = document.querySelectorAll('.tab-btn');

  if (tabName === 'contract') {
    if (contractContainer) contractContainer.style.display = 'block';
    if (declaratieContainer) declaratieContainer.style.display = 'none';
    if (tabs[0]) tabs[0].classList.add('active');
    if (tabs[1]) tabs[1].classList.remove('active');
  } else {
    if (contractContainer) contractContainer.style.display = 'none';
    if (declaratieContainer) declaratieContainer.style.display = 'block';
    if (tabs[0]) tabs[0].classList.remove('active');
    if (tabs[1]) tabs[1].classList.add('active');
  }
}

function closeDocPreview() {
  const modal = document.getElementById('documentPreviewModal');
  if (modal) modal.style.display = 'none';
}

// --- VÉGLEGES BEKÜLDÉS A MODALBÓL ---
async function submitFinalDocs() {
  const confirmBtn = document.querySelector('.btn-confirm');
  if (confirmBtn) {
    confirmBtn.disabled = true;
    confirmBtn.textContent = "Se trimite...";
  }

  try {
    const form = document.getElementById('contractForm');
    const formDataObj = getFormData();

    // 1. Végleges dokumentumok generálása céges aláírással
    const templatePath = (typeof TEMPLATE_B64_CIM !== 'undefined' && TEMPLATE_B64_CIM)
      ? TEMPLATE_B64_CIM
      : 'templates/contract_template.docx';

    const finalContractBlob = await buildDocxBlob(templatePath, true);

    let finalDeclaratieBlob = null;
    if (checkIfDeclaratieNeeded()) {
      const declaratiePath = (typeof TEMPLATE_B64_DECLARATIE !== 'undefined' && TEMPLATE_B64_DECLARATIE)
        ? TEMPLATE_B64_DECLARATIE
        : 'templates/declaratie_template.docx';
      finalDeclaratieBlob = await buildDocxBlob(declaratiePath, true);
    }

    // 2. DataTransfer segítségével csatoljuk a fájlokat
    const dataTransfer = new DataTransfer();

    const fileName = `Contract_${formDataObj.nume.replace(/\s+/g, '_')}.docx`;
    const contractFile = new File([finalContractBlob], fileName, {
      type: "application/vnd.openxmlformats-officedocument.wordprocessingml.document"
    });
    dataTransfer.items.add(contractFile);

    if (finalDeclaratieBlob) {
      const declFileName = `Declaratie_${formDataObj.nume.replace(/\s+/g, '_')}.docx`;
      const declaratieFile = new File([finalDeclaratieBlob], declFileName, {
        type: "application/vnd.openxmlformats-officedocument.wordprocessingml.document"
      });
      dataTransfer.items.add(declaratieFile);
    }

    // 3. Megkeressük a meglévő vagy létrehozunk egy rejtett file inputot `name="attachment"` azonosítóval
    let fileInput = form.querySelector('input[type="file"][name="attachment"]');
    if (!fileInput) {
      fileInput = document.createElement('input');
      fileInput.type = 'file';
      fileInput.name = 'attachment';
      fileInput.style.display = 'none';
      form.appendChild(fileInput);
    }

    // Beállítjuk a generált fájlokat az input mezőbe
    fileInput.files = dataTransfer.files;

    closeDocPreview();

    // 4. Form beküldése
    form.submit();

  } catch (err) {
    console.error("Beküldési hiba:", err);
    alert("Hiba történt a fájl csatolása során: " + err.message);
    if (confirmBtn) {
      confirmBtn.disabled = false;
      confirmBtn.textContent = "Végleges Beküldés";
    }
  }
}